from typing import List, Tuple

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Convert grid_values to a 2D list
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Create a DP table
    dp = [[[0 for _ in range(N+1)] for _ in range(N+1)] for _ in range(N+1)]

    # Fill the DP table
    for i in range(1, N+1):
        for j in range(1, N+1):
            dp[i][j][0] = dp[i][j-1][0] + grid[i-1][j-1]
            dp[i][0][j] = dp[i-1][j][0] + grid[i-1][j-1]

    # Backtrack to find the maximum value on two paths
    max_sum = 0
    for i in range(1, N+1):
        for j in range(1, N+1):
            max_sum = max(max_sum, dp[i][j][0] + dp[N][N][0] - dp[i][N][0] - dp[N][j][0] + dp[i][j][1] + dp[N][N][1] - dp[i][N][1] - dp[N][j][1])

    return max_sum
