from typing import List

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        if coeff > 0 and terms:
            terms.append('+')
        if coeff == -1:
            terms.append('-')
        elif coeff != 1:
            terms.append(str(abs(coeff)))

        if i == 0:
            continue
        elif i == 1:
            terms.append('x')
        else:
            terms.append(f'x^{i}')

    return ''.join(terms)
