def count_partitions(n: int, k: int, x: int) -> int:
    # Base case: if n is less than k times x, it's impossible to partition
    if n < k * x:
        return 0
    # If k is 1, there is only one way to partition n (all parts being n)
    if k == 1:
        return 1
    # If x is 1, the problem reduces to finding the number of partitions of n into k parts without any minimum value constraint
    elif x == 1:
        return count_partitions(n, k, x) if k == 1 else count_partitions(n, k, x + 1) + count_partitions(n, k - 1, 1)
    # Use a recursive approach with memoization to avoid redundant calculations
    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]
    for i in range(n + 1):
        for j in range(min(i, k) + 1):
            if j == 0:
                dp[i][j] = 0
            elif i == j:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i - 1][j] + dp[i - j][j]
    for i in range(x, n + 1):
        for j in range(2, k + 1):
            dp[i][j] -= dp[i - j][j - 1]
    return dp[n][k]
