def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Function to evaluate if a statement is about the day of the week
    def is_day_of_week_statement(statement):
        for day in days_of_week:
            if day in statement:
                return True
        return False

    # Filter out statements about the day of the week
    filtered_statements = {
        participant: [statement for statement in statements[participant] if not is_day_of_week_statement(statement)]
        for participant in statements
    }

    # Function to check if a participant's statements are consistent with them being the criminal
    def is_statement_consistent_with_criminal(statement, participant):
        if participant == scenario:
            return "I am guilty." in statement or "I am not guilty." not in statement
        else:
            return "I am guilty." not in statement or "I am not guilty." in statement

    # Check all participants' statements
    for participant in filtered_statements:
        if participant in liar_count:
            # Liar says the opposite of what they should
            for statement in filtered_statements[participant]:
                if not is_statement_consistent_with_criminal(statement, participant):
                    return False
        else:
            # Truth-teller says what they should
            for statement in filtered_statements[participant]:
                if not is_statement_consistent_with_criminal(statement, participant):
                    return False

    return True
