def calculate_score(system: int, points: str) -> list:
    if system not in [11, 21]:
        raise ValueError("system must be either 11 or 21")

    scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1
        else:
            raise ValueError("points must only contain 'W' and 'L'")

        if player_score >= system or opponent_score >= system:
            if abs(player_score - opponent_score) >= 2:
                scores.append(f"{player_score}:{opponent_score}")
                player_score = 0
                opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores
