def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(n):
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            for k in range(min(a[i], j) + 1):
                new_dp[j] = (new_dp[j] + dp[j - k]) % MOD
        dp = new_dp

    return dp[m]

