def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Initialize lists to store the longest increasing subsequence lengths
    dp_increasing = [1] * n
    dp_decreasing = [1] * n

    # Calculate the longest increasing subsequence length up to each index
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                dp_increasing[i] = max(dp_increasing[i], dp_increasing[j] + 1)

    # Calculate the longest decreasing subsequence length starting from each index
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j]:
                dp_decreasing[i] = max(dp_decreasing[i], dp_decreasing[j] + 1)

    # Find the maximum length of the choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, dp_increasing[i] + dp_decreasing[i] - 1)

    # The minimum number of students to leave is the total number of students
    # minus the maximum length of the choir formation
    return n - max_choir_length
